/** ai.provider-manage-request@1.0.0 (owner: ai) */
/**
 * ai.provider-manage-request@1: bodies of ai.provider.manage on OpenVibe.AI. POST /api/v1/providers creates or replaces a provider (key required) and PATCH /api/v1/providers/:key changes one (fields left out keep their value); a body carrying api_key or secret is refused (422: send secret_ref env:NAME, never a secret value). POST /api/v1/models (provider_key and model_key required) and PATCH /api/v1/models/:provider/:model upsert a model. POST /api/v1/quotas upserts a quota (scope_type and window required; scope_id too unless global; the same scope, window and workflow_prefix is one quota). POST /api/v1/providers/:key/disable|enable|reset and DELETE /api/v1/cache[?workflow=] take no body. Unknown fields are ignored.
 */
export type AiProviderManageRequest =
  | {
      key?: string;
      display_name?: string;
      kind?: "stub" | "openai" | "anthropic" | "http" | "whisper";
      status?: "active" | "disabled";
      base_url?: string | null;
      auth_mode?: "none" | "bearer" | "x-api-key";
      secret_ref?: string | null;
      default_model?: string | null;
      capabilities?: (
        | "chat"
        | "generate"
        | "summarize"
        | "classify"
        | "extract"
        | "enrich"
        | "embed"
        | "vision"
        | "json"
        | "transcribe"
      )[];
      /**
       * Clamped to 1000..600000.
       */
      timeout_ms?: number | string;
      priority?: number | string;
      metadata?: {};
    }
  | {
      provider_key?: string;
      model_key?: string;
      display_name?: string;
      type?: "chat" | "vision" | "embedding" | "stt";
      status?: "active" | "disabled";
      context_window?: number | null;
      max_output?: number | null;
      cost?: {
        in_per_mtok?: number | null;
        out_per_mtok?: number | null;
        cached_per_mtok?: number | null;
      };
      supports?: {
        json?: boolean;
        tools?: boolean;
        streaming?: boolean;
        vision?: boolean;
      };
      metadata?: {};
    }
  | {
      scope_type: "global" | "service" | "actor" | "attribution";
      /**
       * * on a non-global scope = each one separately.
       */
      scope_id?: string;
      window: "minute" | "hour" | "day";
      max_requests?: number | string | null;
      max_tokens?: number | string | null;
      max_cost_usd?: number | string | null;
      workflow_prefix?: string | null;
      status?: "active" | "disabled";
    }
  | NoBody;

/** ai.provider-manage-result@1.0.0 (owner: ai) */
/**
 * ai.provider-manage-result@1: answers of ai.provider.manage on OpenVibe.AI. Provider create/update/disable/enable → { provider } (201 on POST); POST …/reset → { health } (the circuit breaker, closed again); model upserts → { model }; POST /api/v1/quotas → 201 { quota } (the stored row); DELETE /api/v1/cache → { removed } (entries purged). Every change is audited.
 */
export type AiProviderManageResult =
  | {
      provider: AiProvider;
    }
  | {
      health: {
        provider_key?: string;
        state: "closed" | "open" | "half_open";
        consecutive_failures?: number;
      };
    }
  | {
      model: AiModel;
    }
  | {
      quota: {
        id: number;
        scope_type: string;
        scope_id: string;
        window: string;
        max_requests?: number | null;
        max_tokens?: number | null;
        max_cost_usd?: number | null;
        workflow_prefix?: string | null;
        status: string;
      };
    }
  | {
      removed: number;
    };

/** ai.provider@1.0.0 (owner: ai) */
/**
 * ai.provider@1: one model provider as OpenVibe.AI's registry API shows it (server/registry.js publicProvider): never a secret value, only the secret reference name (env:NAME) and whether it resolves (credentials), plus the circuit-breaker health.
 */
export interface AiProvider {
  key: string;
  display_name?: string | null;
  kind: "stub" | "openai" | "anthropic" | "http" | "whisper";
  status: "active" | "disabled";
  base_url?: string | null;
  auth_mode: "none" | "bearer" | "x-api-key";
  /**
   * env:NAME, a reference; never the secret.
   */
  secret_ref?: string | null;
  default_model?: string | null;
  capabilities: (
    "chat" | "generate" | "summarize" | "classify" | "extract" | "enrich" | "embed" | "vision" | "json" | "transcribe"
  )[];
  timeout_ms?: number | null;
  priority?: number | null;
  metadata?: {};
  origin?: string | null;
  created_at?: string | null;
  updated_at?: string | null;
  credentials: "not_required" | "configured" | "missing";
  health?: {
    provider_key?: string;
    state?: "closed" | "open" | "half_open";
    consecutive_failures?: number;
  } | null;
}

/** ai.usage-result@1.0.0 (owner: ai) */
/**
 * ai.usage-result@1: answers of ai.usage.read on OpenVibe.AI (all GETs, parameters in the query). GET /api/v1/status → { providers, runs, today, workflows, templates, routes, inflight, quotas }; GET /api/v1/usage?from=&to=&requester= → { usage } (daily rows); GET /api/v1/quotas → { quotas, current }; GET /api/v1/requests?provider=&status=&run=&fallback=&limit= → { requests } (request-log metadata: hashes, tokens, cost, latency; raw debug fields only for provider managers who ask); GET /api/v1/audit → { audit }; GET /api/v1/cache → { cache }; GET /api/v1/providers → { providers }; GET /api/v1/models?provider= → { models }. Never raw prompts, never secrets.
 */
export type AiUsageResult =
  | {
      providers: {
        key: string;
        kind?: string;
        status?: string;
        credentials?: string;
        health?: string;
      }[];
      /**
       * Run counts by status.
       */
      runs: {
        [k: string]: number | undefined;
      };
      today: {
        day: string;
        requests?: number;
        cost_usd?: number;
      };
      workflows?: number;
      templates?: number;
      routes?: number;
      inflight?: number;
      quotas?: unknown[];
    }
  | {
      providers: AiProvider[];
    }
  | {
      models: AiModel[];
    }
  | {
      quotas: {}[];
      current: {
        quota?: {};
        scope_id?: string;
        window_start?: string;
        resets_in_seconds?: number;
        used?: {};
      }[];
    }
  | {
      usage: {}[];
    }
  | {
      /**
       * @maxItems 500
       */
      requests: {}[];
    }
  | {
      audit: {}[];
    }
  | {
      cache: {
        workflow_key?: string;
        privacy?: string;
        entries?: number;
        hits?: number | null;
      }[];
    };

/** ai.run-citation@1.0.0 (owner: ai) */
/**
 * ai.run-citation@1: one source a run cited on OpenVibe.AI (the citations table): what the workflow was given or a citation the requester attached afterwards (provenance.attached), with trust and provenance.
 */
export interface AiRunCitation {
  id: number;
  run_id: string;
  ordinal?: number | null;
  source_type: string;
  source_id?: string | null;
  url?: string | null;
  title?: string | null;
  author?: string | null;
  published_at?: string | null;
  retrieved_at?: string | null;
  snippet?: string | null;
  content_hash?: string | null;
  trust?: {};
  provenance?: {};
  attached_by?: string | null;
  created_at?: string;
}

/** ai.run-create-request@1.0.0 (owner: ai) */
/**
 * ai.run-create-request@1: bodies of ai.run.create on OpenVibe.AI. POST /api/v1/runs: ai.run-request@1. POST /api/v1/chat, /generate, /summarize, /classify, /extract, /enrich and /embed: a run of workflow ai.<op> whose input is the body itself (validated by that workflow's own input schema), except idempotency_key, target, attribution, on_behalf_of and options, which are the run's. POST /api/v1/runs/:id/citations: { citations } (1-50, each with a source_type; the requester only). POST /api/v1/runs/:id/cancel and /retry take no body.
 */
export type AiRunCreateRequest =
  | AiRunRequest
  | {
      /**
       * @minItems 1
       * @maxItems 50
       */
      citations: [
        {
          source_type: string;
          source_id?: string;
          url?: string;
          title?: string;
          author?: string;
          snippet?: string;
          provenance?: {};
        },
        ...{
          source_type: string;
          source_id?: string;
          url?: string;
          title?: string;
          author?: string;
          snippet?: string;
          provenance?: {};
        }[]
      ];
    }
  | {
      idempotency_key?: string;
      target?: unknown;
      attribution?: unknown;
      on_behalf_of?: unknown;
      options?: {};
    }
  | NoBody;

/** ai.run-create-result@1.0.0 (owner: ai) */
/**
 * ai.run-create-result@1: answers of ai.run.create on OpenVibe.AI. POST /api/v1/runs and the direct operations → { run, replayed? } (201 when it finished or was served from cache within the wait, 202 with Location while queued or running, 200 with replayed true for an idempotent repeat); POST …/cancel → { run }; POST …/retry → { run } (a new run with retry_of); POST …/citations → 201 { citations }. A quota refusal or a full queue is 429 with Retry-After.
 */
export type AiRunCreateResult =
  | {
      run: AiRun;
      replayed?: true;
    }
  | {
      citations: AiRunCitation[];
    };

/** ai.run-read-result@1.0.0 (owner: ai) */
/**
 * ai.run-read-result@1: answers of ai.run.read on OpenVibe.AI (the caller's own runs; usage readers may ask for all). GET /api/v1/runs?status=&workflow=&target=&limit=&before= → { runs }; GET /api/v1/runs/:id → { run, citations, requests } (the request log is metadata only: hashes, tokens, cost, latency, never prompts); GET /api/v1/runs/:id/citations → { citations }. Someone else's run is 404 run.not_found.
 */
export type AiRunReadResult =
  | {
      runs: AiRun[];
    }
  | {
      run: AiRun;
      citations: AiRunCitation[];
      requests: {
        id: number;
        seq: number;
        operation?: string | null;
        provider_key?: string | null;
        model_key?: string | null;
        status: string;
        fallback?: unknown;
        tokens_in?: number | null;
        tokens_out?: number | null;
        cost_usd?: number | null;
        latency_ms?: number | null;
      }[];
    }
  | {
      citations: AiRunCitation[];
    };

/** tips.interaction.ready@1.0.0 (owner: tips) */
/**
 * tips.interaction.ready v1 (OpenVibe.Tips server/domain/interactions.js settle, summary()). The interaction settled: it is active and its effects (overlay alert, chat line, paid message, TTS, media request) are queued. Envelope: subject { type: interaction, id: tint_… }, visibility internal, priority important, actor service:tips. Never emitted for tests or imports.
 */
export interface TipsInteractionReadyPayload {
  interaction_id: string;
  creator: SubjectRef;
  /**
   * The supporter, null when external, anonymous or unmapped.
   */
  supporter: SubjectRef | null;
  /**
   * Display name at the time.
   */
  supporter_name: string | null;
  kind: "tip" | "paid_message" | "tts" | "media_request";
  /**
   * Integer amount in currency minor units (Vibes bits).
   */
  amount: number;
  /**
   * vibes-bits today.
   */
  currency: string;
  settlement: "billing" | "external" | "simulated" | "imported";
  payment_state: "pending" | "settled" | "reversed" | "failed";
  delivery_state: "awaiting_payment" | "queued" | "delivered" | "failed" | "cancelled";
  /**
   * The Billing transaction (txn_…) that settled it.
   */
  billing_txn_id: string | null;
  /**
   * Simulations never emit events, so false in practice.
   */
  test: boolean;
}

/** tips.interaction.failed@1.0.0 (owner: tips) */
/**
 * tips.interaction.failed v1 (OpenVibe.Tips server/domain/interactions.js recomputeDelivery). A delivery effect gave up after its retries and none is still queued; the payment state is untouched. Envelope: subject { type: interaction, id: tint_… }, visibility internal, priority important, actor service:tips. Never emitted for tests or imports.
 */
export interface TipsInteractionFailedPayload {
  interaction_id: string;
  creator: SubjectRef;
  /**
   * The supporter, null when external, anonymous or unmapped.
   */
  supporter: SubjectRef | null;
  /**
   * Display name at the time.
   */
  supporter_name: string | null;
  kind: "tip" | "paid_message" | "tts" | "media_request";
  /**
   * Integer amount in currency minor units (Vibes bits).
   */
  amount: number;
  /**
   * vibes-bits today.
   */
  currency: string;
  settlement: "billing" | "external" | "simulated" | "imported";
  payment_state: "pending" | "settled" | "reversed" | "failed";
  delivery_state: "awaiting_payment" | "queued" | "delivered" | "failed" | "cancelled";
  /**
   * The Billing transaction (txn_…) that settled it.
   */
  billing_txn_id: string | null;
  /**
   * Simulations never emit events, so false in practice.
   */
  test: boolean;
  /**
   * @minItems 1
   */
  failed_effects: [
    {
      effect: "chat_line" | "paid_message" | "tts" | "media_request" | "overlay_alert";
      adapter: string;
      last_error: string | null;
    },
    ...{
      effect: "chat_line" | "paid_message" | "tts" | "media_request" | "overlay_alert";
      adapter: string;
      last_error: string | null;
    }[]
  ];
}

/** tips.interaction.cancelled@1.0.0 (owner: tips) */
/**
 * tips.interaction.cancelled v1 (OpenVibe.Tips server/domain/interactions.js failPayment, cancelQueued). Undelivered effects were cancelled: the payment failed before settling (reason payment_failed, with the Billing error code), Billing reversed it (payment_reversed) or an effect came up while the payment was no longer settled (payment_not_settled). Envelope: subject { type: interaction, id: tint_… }, visibility internal, priority important, actor service:tips. Never emitted for tests or imports.
 */
export interface TipsInteractionCancelledPayload {
  interaction_id: string;
  creator: SubjectRef;
  /**
   * The supporter, null when external, anonymous or unmapped.
   */
  supporter: SubjectRef | null;
  /**
   * Display name at the time.
   */
  supporter_name: string | null;
  kind: "tip" | "paid_message" | "tts" | "media_request";
  /**
   * Integer amount in currency minor units (Vibes bits).
   */
  amount: number;
  /**
   * vibes-bits today.
   */
  currency: string;
  settlement: "billing" | "external" | "simulated" | "imported";
  payment_state: "pending" | "settled" | "reversed" | "failed";
  delivery_state: "awaiting_payment" | "queued" | "delivered" | "failed" | "cancelled";
  /**
   * The Billing transaction (txn_…) that settled it.
   */
  billing_txn_id: string | null;
  /**
   * Simulations never emit events, so false in practice.
   */
  test: boolean;
  reason: "payment_failed" | "payment_reversed" | "payment_not_settled";
  /**
   * Only with reason payment_failed: the Billing problem code (billing.insufficient_funds, billing.funding_reversed, billing.refused…).
   */
  code?: string;
}

/** tips.interaction.moderated@1.0.0 (owner: tips) */
/**
 * tips.interaction.moderated v1 (OpenVibe.Tips server/domain/moderation.js record). A moderation outcome for a paid message (and the name that came with it): the creator's word filter starred words out at settlement (filtered) or held it for review before anything was shown (held); the creator, one of their moderators or a service hid it (hidden: queued chat, TTS and media deliveries were cancelled, the overlay alert retracted, public pages leave it out) or showed it again (restored; a held one is released then). The money is never touched: no refund, the goal and totals keep it. Envelope: subject { type: interaction, id: tint_… }, visibility internal, priority important, actor service:tips. Carries no supporter, message, reason text or moderator identity (Tips keeps those in its own moderation log). Never emitted for simulations.
 */
export interface TipsInteractionModeratedPayload {
  interaction_id: string;
  creator: SubjectRef;
  action: "filtered" | "held" | "hidden" | "restored";
  /**
   * Who acted, by role.
   */
  by: "filter" | "creator" | "moderator" | "service";
  /**
   * The interaction's moderation state after this outcome.
   */
  moderation_state: "visible" | "held" | "hidden";
  /**
   * Deliveries this outcome cancelled before they happened (hidden only; empty otherwise). A consumer that queued the same paid message itself should drop it.
   */
  cancelled_effects: ("chat_line" | "paid_message" | "tts" | "media_request")[];
}

/** tips.interaction.erased@1.0.0 (owner: tips) */
/**
 * tips.interaction.erased v1 (OpenVibe.Tips server/domain/interactions.js erase). The supporter erased their data from this interaction: Tips no longer holds their subject, name, message, text-to-speech text, media link or checkout reference; the money record (amount, creator, Billing transaction, goal contribution) stays so Billing's books and the creator's totals still reconcile. payload.redacts names every earlier Tips event about the interaction, so OpenVibe.Events tombstones them (ADR-026). Envelope: subject { type: interaction, id: tint_… }, visibility internal, priority important, actor service:tips. Carries no supporter data. Never emitted for simulations.
 */
export interface TipsInteractionErasedPayload {
  interaction_id: string;
  creator: SubjectRef;
  erased_at: string;
  redacts: RedactionDirective;
}

/** tips.goal.updated@1.0.0 (owner: tips) */
/**
 * tips.goal.updated v1 (OpenVibe.Tips server/domain/goals.js changed). A goal was created, edited or closed, or its settled total moved (a contribution, the contribution that reached it, a reversal). Envelope: subject { type: goal, id: tgoal_…, revision }, visibility internal, priority important, actor service:tips.
 */
export interface TipsGoalUpdatedPayload {
  goal_id: string;
  creator: SubjectRef;
  title: string;
  target_amount: number;
  /**
   * Settled total including any amount carried over from Live.
   */
  current_amount: number;
  currency: string;
  status: "active" | "closed";
  reached: boolean;
  reason: "created" | "updated" | "closed" | "contribution" | "reached" | "reversal";
  /**
   * The interaction behind a contribution, reached or reversal change; null otherwise.
   */
  interaction_id: string | null;
}

/** tips.overlay.delivered@1.0.0 (owner: tips) */
/**
 * tips.overlay.delivered v1 (OpenVibe.Tips server/domain/overlays.js markDelivered). An overlay delivery (alert or goal update) reached at least one connected overlay, first time only. Envelope: subject { type: overlay_delivery, id: tovd_… }, visibility internal, priority important, actor service:tips. Never for tests.
 */
export interface TipsOverlayDeliveredPayload {
  delivery_id: string;
  creator: SubjectRef;
  kind: "alert" | "goal";
  interaction_id: string | null;
  goal_id: string | null;
}

/** tips.overlay.failed@1.0.0 (owner: tips) */
/**
 * tips.overlay.failed v1 (OpenVibe.Tips server/domain/overlays.js sweepFailed). No overlay showed the delivery within the delivery window. Envelope: subject { type: overlay_delivery, id: tovd_… }, visibility internal, priority important, actor service:tips. Never for tests.
 */
export interface TipsOverlayFailedPayload {
  delivery_id: string;
  creator: SubjectRef;
  kind: "alert" | "goal";
  interaction_id: string | null;
  goal_id: string | null;
  reason: string;
}

/** tips.external-request@1.0.0 (owner: tips) */
/**
 * tips.external-request@1: the body of tips.interaction.record on OpenVibe.Tips (services only). POST /api/v1/interactions/external: { creator, provider, provider_ref, amount_cents, supporter?, supporter_name?, message?, goal_id?, privacy?, announce?, test? } records a tip that never touched OpenVibe money (ADR-012 EXTERNAL: a tip on the creator's own PowerChat), once per (provider, provider_ref); no Billing liability, excluded from Billing reconciliation. It settles at once (overlay alert, goal); announce true also has Tips post the chat line. Needs an Idempotency-Key header (8-200 of A-Z a-z 0-9 . _ : -; 400 idempotency.key_required): a replay with the same key and body returns the first answer, the same key with another body is 422 idempotency.key_reused. Refusals are problem+json: 422 tips.invalid_input (no provider or provider_ref), tips.invalid_amount, tips.text_too_long or tips.invalid_subject; 404 tips.creator_not_found; 403 capability.denied. Unknown fields are ignored.
 */
export interface TipsExternalRequest {
  /**
   * The creator tipped.
   */
  creator: SubjectRef | string;
  /**
   * Lowercased: powerchat, …
   */
  provider: string;
  /**
   * The provider's event id.
   */
  provider_ref: string;
  /**
   * The money that arrived, in cents (at most 100000000); recorded as the amount too.
   */
  amount_cents: number | string;
  /**
   * The supporter, when known.
   */
  supporter?: SubjectRef | string;
  supporter_name?: string | null;
  message?: string | null;
  goal_id?: string;
  /**
   * The supporter's choices; any other field is refused (422 tips.invalid_input). true, 1, "1", "true" and "on" count as yes.
   */
  privacy?: {
    /**
     * The name reads "Anonymous" to everyone but the supporter.
     */
    anonymous?: boolean | number | string;
    /**
     * The amount is left out of overlays, chat lines and public pages.
     */
    hide_amount?: boolean | number | string;
    /**
     * A tip's message is for the creator only (tips only; 422 for the other kinds).
     */
    private_message?: boolean | number | string;
  };
  /**
   * true: Tips delivers the chat line itself (the provider did not announce it).
   */
  announce?: boolean;
  /**
   * Test money: never counted.
   */
  test?: boolean | number | string;
}

/** tips.external-result@1.0.0 (owner: tips) */
/**
 * tips.external-result@1: the answer of tips.interaction.record on OpenVibe.Tips. POST /api/v1/interactions/external → { interaction, duplicate } (201 when recorded; 200 with duplicate true when that provider_ref was recorded before, answering the first interaction). The interaction is funding external, settlement external, in the service view.
 */
export interface TipsExternalResult {
  interaction: TipsInteraction;
  duplicate: boolean;
}

/** tips.goal-create-request@1.0.0 (owner: tips) */
/**
 * tips.goal-create-request@1: the body of tips.goal.create on OpenVibe.Tips. POST /api/v1/goals: { creator?, title, target_amount, description?, image_url?, sort_order? } opens a goal (a service names the creator; a person opens one on their own page). Its total is derived from settled interactions only. Needs an Idempotency-Key header (8-200 of A-Z a-z 0-9 . _ : -; 400 idempotency.key_required): a replay with the same key and body returns the first answer, the same key with another body is 422 idempotency.key_reused. Refusals are problem+json: 422 tips.invalid_input (no title, a bad image_url or sort_order), tips.invalid_amount or tips.text_too_long; 409 tips.too_many_goals (20 active at most); 404 tips.creator_not_found; 403 capability.denied or tips.forbidden. Unknown fields are ignored.
 */
export interface TipsGoalCreateRequest {
  /**
   * The creator (default: the signed-in person).
   */
  creator?: SubjectRef | string;
  title: string;
  /**
   * Vibes bits, at most TIPS_MAX_BITS (10000000 by default).
   */
  target_amount: number | string;
  description?: string | null;
  /**
   * An https URL; empty or null clears it.
   */
  image_url?: string | null;
  sort_order?: number | string;
}

/** tips.goal-result@1.0.0 (owner: tips) */
/**
 * tips.goal-result@1: one goal on OpenVibe.Tips (tips.goal.create, tips.goal.update, tips.goal.close). POST /api/v1/goals (201), PATCH /api/v1/goals/:id and POST /api/v1/goals/:id/close → { goal } (closing keeps its history; closing a closed goal changes nothing). GET /api/v1/goals/:id → { goal }: with contributions for the creator and granted services, else the public shape (404 tips.goal_not_found when the page is off).
 */
export interface TipsGoalResult {
  goal: TipsGoal;
}

/** tips.goal-update-request@1.0.0 (owner: tips) */
/**
 * tips.goal-update-request@1: bodies of tips.goal.update on OpenVibe.Tips. PATCH /api/v1/goals/:id: { title?, target_amount?, description?, image_url?, sort_order?, revision? } edits an active goal; revision, when given, must be the goal's current revision (409 tips.revision_conflict). Needs an Idempotency-Key header (8-200 of A-Z a-z 0-9 . _ : -; 400 idempotency.key_required): a replay with the same key and body returns the first answer, the same key with another body is 422 idempotency.key_reused. GET /api/v1/goals/:id (reading it, with contributions for the creator and granted services) takes no body. Refusals are problem+json: 404 tips.goal_not_found; 409 tips.goal_closed or tips.revision_conflict; 422 tips.invalid_input, tips.invalid_amount or tips.text_too_long. Unknown fields are ignored.
 */
export type TipsGoalUpdateRequest =
  | {
      title?: string;
      /**
       * Vibes bits, at most TIPS_MAX_BITS (10000000 by default).
       */
      target_amount?: number | string;
      description?: string | null;
      /**
       * An https URL; empty or null clears it.
       */
      image_url?: string | null;
      sort_order?: number | string;
      revision?: number | string;
    }
  | NoBody;

/** tips.goal@1.0.0 (owner: tips) */
/**
 * tips.goal@1: a creator's goal on OpenVibe.Tips (server/domain/goals.js present, publicGoal). current_amount is derived from settled contributions (plus an amount carried over from Live), never from pending or simulated tips; percent is capped at 100. Anyone but the creator and granted services gets the public shape under the creator's page settings: amounts null with amounts_hidden when goal amounts are off, and supporters (the latest ten, their privacy applying) when goal supporters are on. GET /api/v1/goals/:id adds contributions for the creator and granted services.
 */
export interface TipsGoal {
  id: string;
  creator: SubjectRef;
  title: string;
  description: string | null;
  target_amount: number | null;
  current_amount: number | null;
  currency: string;
  /**
   * Contributions counted.
   */
  supporters_count: number;
  carried_over_amount: number | null;
  percent: number;
  reached: boolean;
  reached_at: string | null;
  image_url: string | null;
  status: "active" | "closed";
  sort_order: number;
  revision: number;
  created_at: string;
  updated_at: string;
  closed_at: string | null;
  amounts_hidden?: true;
  supporters?: {
    name: string;
    amount: number | null;
    at: string;
  }[];
  contributions?: {
    interaction_id: string;
    amount: number;
    reversed_amount: number;
    created_at: string;
    supporter_name: string;
  }[];
}

/** tips.interaction-list-result@1.0.0 (owner: tips) */
/**
 * tips.interaction-list-result@1: answers of tips.interaction.list on OpenVibe.Tips. GET /api/v1/interactions?creator=&supporter=&include_test=&cursor=&limit= → { interactions, next_cursor }: newest first, at most 200 a page (50 by default); a service names a creator or a supporter (422 tips.invalid_input otherwise); a person gets their own receipts, or with ?as=creator the tips they received. include_test=0 leaves simulations out. GET /api/v1/profiles/:creator/totals → { creator, totals }: derived from settled interactions; settled_via_billing is what must equal Billing's books (minus what Billing took back), external and simulations are reported apart.
 */
export type TipsInteractionListResult =
  | {
      interactions: TipsInteraction[];
      next_cursor: string | null;
    }
  | {
      creator: SubjectRef;
      totals: {
        currency: "vibes-bits";
        /**
         * Bits settled through Billing (or imported from Live's ledger), less reversals.
         */
        settled_via_billing: number;
        /**
         * Bits of EXTERNAL tips (the creator's own PowerChat): no Billing liability.
         */
        external: number;
        /**
         * Settled or reversed interactions, simulations excluded.
         */
        interactions: number;
        simulations: number;
        pending: number;
      };
    };

/** tips.interaction-result@1.0.0 (owner: tips) */
/**
 * tips.interaction-result@1: one interaction on OpenVibe.Tips (tips.interaction.get, tips.simulation.run). GET /api/v1/interactions/:id → { interaction } in the reader's view (a service, the creator, or the supporter; anyone else 404 tips.interaction_not_found). POST /api/v1/simulate (201) → { interaction }: the simulated interaction (test true, settlement simulated), in the creator's view.
 */
export interface TipsInteractionResult {
  interaction: TipsInteraction;
}

/** tips.interaction@1.0.0 (owner: tips) */
/**
 * tips.interaction@1: a tip interaction on OpenVibe.Tips (server/domain/interactions.js present): one act of support (a tip, a paid chat message, text-to-speech or a media request) with two separate states: payment (mirrored from OpenVibe.Billing: pending, settled, reversed or failed) and delivery (awaiting_payment, queued, delivered, failed or cancelled). Only the supporter sees who an anonymous supporter is; public is what may be shown to the public and privacy the supporter's choices. A checkout-funded interaction adds checkout; the creator and services also get effects, provider, provider_ref and legacy_source. Amounts are Vibes bits.
 */
export interface TipsInteraction {
  id: string;
  creator: SubjectRef;
  /**
   * null for an anonymous supporter (to anyone but them), an erased one, a simulation or an external tip without one.
   */
  supporter: SubjectRef | null;
  supporter_name: string | null;
  kind: "tip" | "paid_message" | "tts" | "media_request";
  amount: number;
  /**
   * vibes-bits.
   */
  currency: string;
  message: string | null;
  tts: {
    text: string;
    voice: string;
  } | null;
  media: {
    url: string;
    provider?: string;
  } | null;
  /**
   * The goal the supporter picked.
   */
  goal_id: string | null;
  funding: "credit" | "checkout" | "provider" | "external" | "none";
  settlement: "billing" | "external" | "simulated" | "imported";
  origin: "tips" | "billing" | "billing-external" | "external" | "import";
  /**
   * A simulation or Billing test money: never counted.
   */
  test: boolean;
  privacy: {
    anonymous: boolean;
    hide_amount: boolean;
    private_message: boolean;
  };
  public: TipsPublicInteraction;
  /**
   * When the supporter erased their data from it.
   */
  erased_at: string | null;
  moderation: {
    state: "visible" | "held" | "hidden";
    filtered: boolean;
    at: string | null;
  };
  payment: {
    state: "pending" | "settled" | "reversed" | "failed";
    billing_txn_id: string | null;
    reversal_txn_ids: string[];
    reversed_amount: number;
    failure: string | null;
    settled_at: string | null;
    reversed_at: string | null;
  };
  delivery: {
    state: "awaiting_payment" | "queued" | "delivered" | "failed" | "cancelled";
    delivered_at: string | null;
  };
  created_at: string;
  updated_at: string;
  /**
   * Checkout-funded interactions only.
   */
  checkout?: {
    url: string | null;
    ref: string | null;
    provider: string | null;
    intent_id: string | null;
  };
  /**
   * The creator and services only: the delivery effects.
   */
  effects?: {
    effect: "chat_line" | "paid_message" | "tts" | "media_request" | "overlay_alert";
    adapter: string;
    state: "queued" | "delivered" | "failed" | "cancelled";
    attempts: number;
    last_error: string | null;
    updated_at: string;
  }[];
  provider?: string | null;
  provider_ref?: string | null;
  legacy_source?: string | null;
}

/** tips.moderation-request@1.0.0 (owner: tips) */
/**
 * tips.moderation-request@1: bodies of tips.interaction.moderate on OpenVibe.Tips. POST /api/v1/interactions/:id/hide and /restore: { reason? } (at most 200 characters, kept in the moderation log). GET /api/v1/moderation?creator=&state=held|hidden|visible|all&cursor=&limit= and GET /api/v1/moderation/log?creator= take no body. The creator, one of their moderators, or a service holding the capability moderates (the log is for the creator and services). Hide and restore need an Idempotency-Key header (as every write). Refusals are problem+json: 404 tips.interaction_not_found, 403 tips.forbidden or capability.denied, 422 tips.text_too_long.
 */
export type TipsModerationRequest =
  | {
      reason?: string | null;
    }
  | NoBody;

/** tips.moderation-result@1.0.0 (owner: tips) */
/**
 * tips.moderation-result@1: answers of tips.interaction.moderate on OpenVibe.Tips. Moderation never touches the money (no refund, no uncounting). GET /api/v1/moderation → { creator, interactions, next_cursor }: the review queue, newest first (moderators' view). GET /api/v1/moderation/log → { log }: the latest 100 outcomes (held and filtered by the word filter at settlement; hidden and restored by the creator, a moderator or a service). POST /api/v1/interactions/:id/hide → { interaction, changed, cancelled_effects } (chat, TTS and media deliveries still queued are cancelled; overlays drop the alert); POST …/restore → the same, cancelled_effects empty (a held interaction is released now; what a hide cancelled stays cancelled). changed false when it already was in that state.
 */
export type TipsModerationResult =
  | {
      creator: SubjectRef;
      interactions: TipsModerationView[];
      next_cursor: string | null;
    }
  | {
      log: {
        interaction_id: string;
        action: "held" | "filtered" | "hidden" | "restored";
        by_role: "filter" | "creator" | "moderator" | "service";
        /**
         * usr_… or svc:…; null for the filter.
         */
        actor: string | null;
        reason: string | null;
        created_at: string;
      }[];
    }
  | {
      interaction: TipsModerationView;
      changed: boolean;
      cancelled_effects: ("chat_line" | "paid_message" | "tts" | "media_request")[];
    };

/** tips.moderation-view@1.0.0 (owner: tips) */
/**
 * tips.moderation-view@1: a tip interaction as its moderators see it on OpenVibe.Tips (server/domain/moderation.js present): what was written (never a private message, nor anything the supporter erased), the moderation state, and what the public sees (public). An anonymous supporter reads Anonymous; a hidden amount is null.
 */
export interface TipsModerationView {
  id: string;
  kind: "tip" | "paid_message" | "tts" | "media_request";
  created_at: string;
  settled_at: string | null;
  payment_state: "pending" | "settled" | "reversed" | "failed";
  test: boolean;
  moderation: {
    state: "visible" | "held" | "hidden";
    at: string | null;
    filtered: boolean;
  };
  supporter_name: string;
  amount: number | null;
  message: string | null;
  tts_text: string | null;
  media_url: string | null;
  public: TipsPublicInteraction;
}

