/** games.mod.grants_changed@1.0.0 (owner: games) */
/**
 * games.mod.grants_changed v1 (OpenVibe.Games apps/server/src/platform/gameEvents.ts modEvent, via ModRegistry.grant and ModRegistry.revokeGrant in mods/registry.ts; POST /api/v1/mods/:id/grants, DELETE /api/v1/mods/:id/grants/:capability). One capability of a non-revoked install was granted (granted: [capability], revoked: []) or one active grant was revoked (granted: [], revoked: [capability]); each call changes exactly one capability today. Not emitted when nothing changed. Revoking the whole install is games.mod.revoked instead. Written to Games' event_outbox in the same SQLite transaction as the registry and mod_audit rows (mods/registry.ts). The manifest, content pack, audit actor string and installer are left out. No consumer yet. Envelope: subject { type: mod, id: <mod.id> }, visibility internal, priority low, actor the staff member who made the change (user:<usr_...>), service:<client> for a principal token carrying games.mod.manage, or service:games (pre-subject staff token, editor key).
 */
export interface GamesModGrantsChangedPayload {
  /**
   * The install, from its validated mods/mod-manifest.v1 manifest.
   */
  mod: {
    /**
     * Mod id (manifest id). Also the envelope subject id.
     */
    id: string;
    name: string;
    /**
     * Semantic version of the installed release.
     */
    version: string;
    /**
     * Manifest target. Games only accepts games.browser today (mods/manifest.ts checkForGames).
     */
    target: string;
    /**
     * Install metadata set at install; never consulted by a grant check.
     */
    trust_tier: "unreviewed" | "reviewed" | "first-party";
  };
  /**
   * Capabilities newly granted by this change.
   *
   * @maxItems 64
   */
  granted: string[];
  /**
   * Capabilities whose grant this change revoked.
   *
   * @maxItems 64
   */
  revoked: string[];
}

/** games.mod.revoked@1.0.0 (owner: games) */
/**
 * games.mod.revoked v1 (OpenVibe.Games apps/server/src/platform/gameEvents.ts modEvent, via ModRegistry.revoke in mods/registry.ts; POST /api/v1/mods/:id/revoke). Terminal: every active grant of the install was revoked and its status set to revoked; the runtime retracts the mod's announcements and props on the next tick. revoked_grants lists the grants that were active (may be empty); reason is the staff-supplied text (cut to 500 characters), absent when none was given. Not emitted again for an install that is already revoked. Written to Games' event_outbox in the same SQLite transaction as the registry and mod_audit rows (mods/registry.ts). The manifest, content pack, audit actor string and installer are left out. No consumer yet. Envelope: subject { type: mod, id: <mod.id> }, visibility internal, priority important, actor the staff member who made the change (user:<usr_...>), service:<client> for a principal token carrying games.mod.manage, or service:games (pre-subject staff token, editor key).
 */
export interface GamesModRevokedPayload {
  /**
   * The install, from its validated mods/mod-manifest.v1 manifest.
   */
  mod: {
    /**
     * Mod id (manifest id). Also the envelope subject id.
     */
    id: string;
    name: string;
    /**
     * Semantic version of the installed release.
     */
    version: string;
    /**
     * Manifest target. Games only accepts games.browser today (mods/manifest.ts checkForGames).
     */
    target: string;
    /**
     * Install metadata set at install; never consulted by a grant check.
     */
    trust_tier: "unreviewed" | "reviewed" | "first-party";
  };
  /**
   * Grants active before the revoke, sorted.
   *
   * @maxItems 64
   */
  revoked_grants: string[];
  reason?: string;
}

/** games.moderation.action@1.0.0 (owner: games) */
/**
 * games.moderation.action v1 (ADR-022, roadmap WS-D task 1). A staff or moderator action on someone else's content or account in OpenVibe.Games, such as kicking or banning a player, lifting a ban, and revoking or disabling someone else's mod. Not a person acting on their own content. Written to the service's outbox in the transaction that performs the action; OpenVibe.Network keeps it in the moderation audit log. The payload is common.moderation-action@1. Envelope: subject { type: moderation_action, id: <target type>:<target id> }, visibility internal, actor the staff member. Never carries the content itself.
 */
export interface GamesModerationActionPayload {
  /**
   * A short verb id, as the service names it: <thing>.<what happened> (post.hidden, user.banned, release.revoked, guard.blocked).
   */
  action: string;
  target: {
    /**
     * What was acted on, in the service's own words (post, page, release, user, player, …).
     */
    type: string;
    id: string;
    /**
     * Whose content or account it was, when known.
     */
    owner_subject?: string | null;
  };
  /**
   * The staff member or moderator (null only for a service acting without a person).
   */
  actor_subject: string | null;
  reason?: string | null;
  /**
   * Per action: the fields changed, the previous and new state, a bulk action's count, … never the content.
   */
  details?: {};
}

/** games.announce-frame@1.0.0 (owner: games) */
/**
 * games.announce-frame@1: the frame OpenVibe.Games broadcasts to every connected player for an announcement (gameServer broadcastAll): { t: announce, text }. A mod's announcement text is prefixed with its name in brackets ([Mod name] text); the binding itself returns nothing.
 */
export interface GamesAnnounceFrame {
  t: "announce";
  text: string;
}

/** games.announcement@1.0.0 (owner: games) */
/**
 * games.announcement@1: what a mod announces through games.world.announce on OpenVibe.Games. Not an HTTP route: the mod runtime binding ModApi.announce(text) (apps/server/src/mods/runtime.ts), driven by the announcements section of the mod's games-content@1 pack (validated strictly: text 1-200 characters, repeated every everySeconds, 60 to 86400). The text is whitespace-collapsed and cut to 200 characters; an empty one is dropped.
 */
export interface GamesAnnouncement {
  text: string;
  everySeconds: number;
}

/** games.mod-manage-result@1.0.0 (owner: games) */
/**
 * games.mod-manage-result@1: answers of games.mod.manage on OpenVibe.Games (staff: an owner/admin session, or a service token with games.mod.manage). POST /api/v1/mods → 201 the installed mod's public view; POST /api/v1/mods/:id/enable|disable|revoke, POST /api/v1/mods/:id/grants and DELETE /api/v1/mods/:id/grants/:capability → 200 the mod's public view after the change (revoke is terminal); GET /api/v1/mods/:id/audit?limit= → { audit } (install, grant, use, deny and revoke entries, at most 500). Errors are problem+json (mod.not_found, mod.invalid_request, capability.denied, …).
 */
export type GamesModManageResult =
  | GamesModView
  | {
      /**
       * @maxItems 500
       */
      audit: {
        id?: number;
        modId: string;
        action: string;
        capability?: string | null;
        actor: string;
        detail?: {} | null;
        /**
         * ms epoch.
         */
        at: number;
      }[];
    };

/** games.prop-placement-result@1.0.0 (owner: games) */
/**
 * games.prop-placement-result@1: what the games.prop.place binding returns on OpenVibe.Games: placeProp → the placed entity's id (null when the host placed nothing); removeProp → true when a prop with that key was removed, false when there was none. A mod without the grant gets a capability.denied error instead; every use is audited.
 */
export type GamesPropPlacementResult = string | null | boolean;

/** games.prop-placement@1.0.0 (owner: games) */
/**
 * games.prop-placement@1: what a mod asks through games.prop.place on OpenVibe.Games. Not an HTTP route: the mod runtime binding ModApi.placeProp(key, item, pos, yaw) / removeProp(key) (apps/server/src/mods/runtime.ts), driven by the props section of the mod's games-content@1 pack, which the registry validates strictly (unknown fields refused). A placement puts an inert prop owned by the mod at pos (re-placing the one with the same key); the item must be placeable by mods and the numbers finite. A removal names only the key.
 */
export type GamesPropPlacement =
  | {
      key: string;
      item: string;
      /**
       * @minItems 3
       * @maxItems 3
       */
      pos: [number, number, number];
      yaw?: number;
    }
  | {
      key: string;
    };

/** games.mod-manage-request@1.0.0 (owner: games) */
/**
 * games.mod-manage-request@1: bodies of games.mod.manage on OpenVibe.Games (staff: an owner/admin session, or a service token with games.mod.manage). POST /api/v1/mods installs a mod: { manifest, pack?, approve?, trustTier?, enable? } — manifest is a mods.mod-manifest@1 the Games runtime can run (games.browser, games-content@1); pack is its games-content@1 data (announcements and props, validated strictly: unknown keys refused); approve lists at most 64 requested capabilities to grant; trustTier is unreviewed (default), reviewed or first-party; enable true starts it enabled. A mod already installed is 409 mod.exists. POST /api/v1/mods/:id/grants: { capability }. POST /api/v1/mods/:id/revoke: { reason? } (terminal). POST /api/v1/mods/:id/enable|disable take an empty JSON object or no body; DELETE /api/v1/mods/:id/grants/:capability and GET /api/v1/mods/:id/audit take no body. Bodies are at most 256 KB; unknown top-level fields are ignored.
 */
export type GamesModManageRequest =
  | {
      manifest: ModManifest;
      pack?: {
        /**
         * @maxItems 10
         */
        announcements?:
          | []
          | [GamesAnnouncement]
          | [GamesAnnouncement, GamesAnnouncement]
          | [GamesAnnouncement, GamesAnnouncement, GamesAnnouncement]
          | [GamesAnnouncement, GamesAnnouncement, GamesAnnouncement, GamesAnnouncement]
          | [GamesAnnouncement, GamesAnnouncement, GamesAnnouncement, GamesAnnouncement, GamesAnnouncement]
          | [
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement
            ]
          | [
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement
            ]
          | [
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement
            ]
          | [
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement
            ]
          | [
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement,
              GamesAnnouncement
            ];
        /**
         * @maxItems 50
         */
        props?: {
          key: string;
          item: string;
          /**
           * @minItems 3
           * @maxItems 3
           */
          pos: [number, number, number];
          yaw?: number;
        }[];
      };
      /**
       * @maxItems 64
       */
      approve?: string[];
      trustTier?: "unreviewed" | "reviewed" | "first-party";
      enable?: boolean;
    }
  | {
      capability: string;
    }
  | {
      /**
       * Revoke only; cut to 500 characters.
       */
      reason?: string;
    };

/** games.mod-read-result@1.0.0 (owner: games) */
/**
 * games.mod-read-result@1: answers of games.mod.read on OpenVibe.Games (public). GET /api/v1/mods → { mods } (every installed mod's public view: status and grants); GET /api/v1/mods/:id → one mod's public view with its installed manifest (mods.mod-manifest@1) and pack. An unknown id is 404 mod.not_found.
 */
export type GamesModReadResult =
  | {
      mods: GamesModView[];
    }
  | (GamesModView & {
      manifest: ModManifest;
      pack: {};
    });

/** games.mod-view@1.0.0 (owner: games) */
/**
 * games.mod-view@1: an installed mod's public view on OpenVibe.Games (apps/server/src/mods/routes.ts publicView): identity, runtime, trust tier, lifecycle status, the capabilities its manifest requests and those currently granted.
 */
export interface GamesModView {
  id: string;
  name: string;
  version: string;
  /**
   * e.g. games.browser
   */
  target: string;
  /**
   * e.g. games-content@1
   */
  runtime: string;
  trust_tier: "unreviewed" | "reviewed" | "first-party";
  status: "enabled" | "disabled" | "revoked";
  /**
   * Capabilities the manifest asks for.
   */
  requested: string[];
  /**
   * Capabilities approved and not revoked.
   */
  granted: string[];
  installed_at: string;
  updated_at: string;
}

/** media.object.deleted@1.0.0 (owner: media) */
/**
 * media.object.deleted v1 (OpenVibe.Media server/events.js objectChangeEvent and recordObjectChanges, commit 039dc48, from the media_object_changes rows that the AFTER UPDATE OF lifecycle_status trigger on media_objects writes). An object's lifecycle_status became deleted: a native object soft-deleted through DELETE /api/v2/:app/objects/:id, or an inherited vods/clips/files/pastes row removed, which marks its object deleted. Every write path counts (operator SQL included), and the event exists if and only if the change committed: the trigger row and the outbox envelope are written in the transaction of the change, or by the relay's drain for a change made outside Media's own transactions. Consumers drop any public copy, index entry or cache they hold for the object (roadmap §29.3). Deliberately minimal, identity and state only: never the title, description or metadata, the owner's ids or subject, storage keys, paths or providers, sizes or hashes. Developer-project sandbox tenants produce none. Envelope: subject { type: object, id: <object_id> }, visibility internal, priority important, actor service:media.
 */
export interface MediaObjectDeletedPayload {
  object_id: string;
  /**
   * The tenant that owns the object: an app (live, tools…) or a developer project's production tenant (prj_…).
   */
  app_id: string;
  kind: "vod" | "clip" | "file" | "thumbnail" | "screenshot" | "avatar" | "asset";
  /**
   * The inherited row the object projects (legacy:<app>:<kind>:<id>, a media.media-ref@1 legacy id); null for a native v2 object.
   */
  legacy_ref: string | null;
  /**
   * When the change committed, ISO 8601 UTC.
   */
  deleted_at: string;
}

/** media.object.visibility_changed@1.0.0 (owner: media) */
/**
 * media.object.visibility_changed v1 (OpenVibe.Media server/events.js objectChangeEvent and recordObjectChanges, commit 039dc48, from the media_object_changes rows that the AFTER UPDATE OF visibility trigger on media_objects writes). An object's visibility changed to another value (public, unlisted or private), by any write path: the v2 objects API, the inherited vods/clips/files rows it projects, or operator SQL. Never emitted when the value did not change, nor for an object that is deleted at the time of the change (that object's last word is media.object.deleted). The event exists if and only if the change committed: the trigger row and the outbox envelope are written in the transaction of the change, or by the relay's drain for a change made outside Media's own transactions. Consumers that hold a public copy, index entry or cache of the object re-check it (roadmap §29.3); a move away from public means stop showing it. Deliberately minimal, identity and state only: never the title, description or metadata, the owner's ids or subject, storage keys, paths or providers, sizes or hashes. Developer-project sandbox tenants produce none. Envelope: subject { type: object, id: <object_id> }, visibility internal, priority important, actor service:media.
 */
export interface MediaObjectVisibilityChangedPayload {
  object_id: string;
  /**
   * The tenant that owns the object: an app (live, tools…) or a developer project's production tenant (prj_…).
   */
  app_id: string;
  kind: "vod" | "clip" | "file" | "thumbnail" | "screenshot" | "avatar" | "asset";
  /**
   * The inherited row the object projects (legacy:<app>:<kind>:<id>, a media.media-ref@1 legacy id); null for a native v2 object.
   */
  legacy_ref: string | null;
  /**
   * The new value.
   */
  visibility: "public" | "unlisted" | "private";
  /**
   * The value before the change; never equal to visibility.
   */
  previous_visibility: "public" | "unlisted" | "private";
  /**
   * When the change committed, ISO 8601 UTC.
   */
  changed_at: string;
}

/** media.file-read-result@1.0.0 (owner: media) */
/**
 * media.file-read-result@1: answers of media.object.read on OpenVibe.Media. GET /api/v1/:app/files/:key → media.file@1 (the file's metadata; 404 when it is not the tenant's); GET /f/:key → the bytes, with Content-Type and Range (a sandbox file only through its signed URL).
 */
export type MediaFileReadResult = MediaFile | string;

/** media.file@1.0.0 (owner: media) */
/**
 * media.file@1: one stored file of a tenant on OpenVibe.Media (server/files/routes.js filePublic): its key, owner, name, size, type and hash, and the URL it is served from (/f/<key>; a developer-project sandbox file gets a short-lived signed URL instead).
 */
export interface MediaFile {
  key: string;
  app_id: string;
  user_id?: string | number | null;
  original_name: string;
  size: number;
  mime: string;
  sha256?: string | null;
  url: string;
  sandbox?: true;
  url_expires_at?: string | number;
  created_at: string;
}

/** media.object@1.0.0 (owner: media) */
/**
 * media.object@1: one object of the OpenVibe.Media object API v2 (/api/v2/:app/objects; Media server/objects/model.js objectPublic): its id and legacy ref, tenant and namespace (the tenant's root, or a namespace below it), kind, owner, visibility, lifecycle, type, size and hash, readiness, and where it is served. Copies are described by provider and state, never by path or key. More fields may be added.
 */
export interface MediaObject {
  id: string;
  media_ref?: MediaRef;
  /**
   * legacy:<app>:<kind>:<id> for an object projected from a VOD, clip, file or paste row; null for a native v2 object.
   */
  legacy_ref?: string | null;
  /**
   * The tenant: an app id, or prj_<ULID> / prj_<ULID>-sandbox for a developer project.
   */
  app_id: string;
  /**
   * The namespace grants name: the tenant's root (its app id; app.<project_id> or app.<project_id>.sandbox for a developer project) or a namespace below it (<root>.<segment>…).
   */
  namespace: string;
  kind: "vod" | "clip" | "file" | "thumbnail" | "screenshot" | "avatar" | "asset";
  owner?: {
    subject?: string | null;
    app?: string | null;
    user_id?: number | null;
  };
  visibility: "public" | "unlisted" | "private";
  lifecycle_status: "uploading" | "ready" | "failed" | "archived" | "deleted";
  mime_type?: string | null;
  size_bytes: number;
  /**
   * sha256 hex of the bytes, once known.
   */
  content_hash?: string | null;
  metadata?: {};
  /**
   * Under a retention hold (its own, or a clip's source VOD's).
   */
  held?: boolean;
  readiness?: {
    metadata?: boolean;
    bytes_verified?: boolean;
    playable?: boolean;
    reason?: string | null;
  };
  /**
   * Where a public or unlisted ready object is served; null for private and sandbox objects (download signs them).
   */
  public_url?: string | null;
  sandbox?: true;
  locations?: {
    provider: "local" | "b2" | "r2";
    storage_class?: string | null;
    state: "present" | "missing" | "pending" | "corrupt";
    size_bytes?: number | null;
    verified_at?: string | null;
    canonical?: boolean;
  }[];
  created_at: string;
  updated_at?: string | null;
  deleted_at?: string | null;
}

/** media.object-list@1.0.0 (owner: media) */
/**
 * media.object-list@1: a page of GET /api/v2/:app/objects (media.object.list), newest first: the objects the caller may list in the tenant (a Network token sees only the namespaces its grant covers; ?namespace= narrows to one namespace and those below it), without their locations, and the cursor of the next page (null on the last).
 */
export interface MediaObjectList {
  objects: MediaObject[];
  next_cursor: string | null;
  limit: number;
}

